"""`mac vpn` — generated by tools/gen_groups.py from local-mac's vpn__* handlers. Do not edit."""
import argparse

from mac.groups._backend import call, given


def register(registry):
    @registry.verb("vpn", "status", mode="read",
                   desc='get Surfshark VPN connection status — connected/disconnected, server location, protocol, DNS, and post-quantum status')
    def vpn_status(ns):
        return call('vpn', 'status')

    @registry.verb("vpn", "connect", mode="write",
                   desc='connect Surfshark VPN (reconnects the WireGuard config)')
    def vpn_connect(ns):
        return call('vpn', 'connect')

    @registry.verb("vpn", "disconnect", mode="write",
                   desc='disconnect Surfshark VPN')
    def vpn_disconnect(ns):
        return call('vpn', 'disconnect')

    def vpn_pause_args(p):
        p.add_argument('--minutes', default=argparse.SUPPRESS, type=int)

    @registry.verb("vpn", "pause", mode="write",
                   desc='pause Surfshark VPN for a set number of minutes (1–480), then auto-reconnect. Default: 30 min', args=vpn_pause_args)
    def vpn_pause(ns):
        return call('vpn', 'pause', **given(ns, ('minutes',)))
